package ru.neverland.mintcontracts.orders;

import java.sql.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

/** Runs only on ServerMaterials' single SQLite worker, inside its transaction for every mutation. */
final class CooperativeProjects {
    private CooperativeProjects(){}
    static void migrate(Connection c)throws SQLException{try(var s=c.createStatement()){
        s.execute("CREATE TABLE IF NOT EXISTS cooperative_projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('SERVER','CITY')),owner_town TEXT NOT NULL,unlock_key TEXT NOT NULL,min_credit INTEGER NOT NULL CHECK(min_credit>0),state TEXT NOT NULL CHECK(state IN ('OPEN','COMPLETED','CANCELLED')),created INTEGER NOT NULL,completed INTEGER NOT NULL DEFAULT 0)");
        s.execute("CREATE TABLE IF NOT EXISTS cooperative_needs(project TEXT NOT NULL REFERENCES cooperative_projects(id),material TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(project,material))");
        s.execute("CREATE TABLE IF NOT EXISTS cooperative_context(delivery TEXT PRIMARY KEY REFERENCES deliveries(id),project TEXT NOT NULL REFERENCES cooperative_projects(id),town TEXT NOT NULL,player TEXT NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS cooperative_contributions(delivery TEXT PRIMARY KEY REFERENCES deliveries(id),project TEXT NOT NULL REFERENCES cooperative_projects(id),town TEXT NOT NULL,player TEXT NOT NULL,material TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),allocation TEXT NOT NULL UNIQUE REFERENCES allocations(id),confirmed INTEGER NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS cooperative_actions(project TEXT NOT NULL REFERENCES cooperative_projects(id),action TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(project,action))");
        s.execute("CREATE INDEX IF NOT EXISTS cooperative_contributions_project ON cooperative_contributions(project,material)");
        s.execute("CREATE INDEX IF NOT EXISTS cooperative_contributions_town ON cooperative_contributions(town,project)");
    }}
    static void id(String value){if(value==null||!value.matches("[a-z0-9_]{1,48}"))throw new IllegalArgumentException("Неверный ID общей стройки");}
    static String town(String value){if(value==null||value.isEmpty())return "";return UUID.fromString(value).toString();}
    static void text(String value,int max,String name){if(value==null||value.isBlank()||value.length()>max)throw new IllegalArgumentException("Неверное поле: "+name);}
    static Map<String,Long> needs(Map<String,Long> source){var result=Map.copyOf(source);if(result.isEmpty()||result.size()>256)throw new IllegalArgumentException("Нужна смета из 1–256 материалов");long total=0;for(var e:result.entrySet()){if(!e.getKey().matches("[A-Z0-9_]{1,64}")||e.getValue()<1||e.getValue()>1_000_000_000L)throw new IllegalArgumentException("Неверная смета общей стройки");total=Math.addExact(total,e.getValue());}return result;}
    static Map<String,Object> plan(Connection c,String id,String title,String scope,String owner,String unlock,long minimum,Map<String,Long> costs,String actor)throws SQLException{
        id(id);text(title,128,"название");text(actor,64,"автор");id(unlock);owner=town(owner);if(!Set.of("SERVER","CITY").contains(scope)||scope.equals("CITY")==owner.isEmpty()||minimum<1||minimum>1_000_000_000L)throw new IllegalArgumentException("Неверные условия общей стройки");var needs=needs(costs);if(minimum>needs.values().stream().mapToLong(Long::longValue).sum())throw new IllegalArgumentException("Порог участия больше всей сметы");
        var old=project(c,id);if(!old.isEmpty()){if(!old.get("title").equals(title)||!old.get("scope").equals(scope)||!old.get("ownerTown").equals(owner)||!old.get("unlock").equals(unlock)||!old.get("minimumCredit").equals(minimum)||!old.get("needs").equals(needs))throw new IllegalArgumentException("Смета закреплена; для других условий нужен новый ID");return old;}
        try(var s=c.createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM cooperative_projects WHERE state='OPEN'")){if(r.next()&&r.getInt(1)>=1000)throw new IllegalArgumentException("Слишком много открытых общих строек");}
        try(var s=c.prepareStatement("INSERT INTO cooperative_projects(id,title,scope,owner_town,unlock_key,min_credit,state,created) VALUES(?,?,?,?,?,?,'OPEN',?)")){s.setString(1,id);s.setString(2,title);s.setString(3,scope);s.setString(4,owner);s.setString(5,unlock);s.setLong(6,minimum);s.setLong(7,System.currentTimeMillis());s.executeUpdate();}
        for(var e:needs.entrySet())try(var s=c.prepareStatement("INSERT INTO cooperative_needs VALUES(?,?,?)")){s.setString(1,id);s.setString(2,e.getKey());s.setLong(3,e.getValue());s.executeUpdate();}log(c,id,"PLAN",actor,title);return project(c,id);
    }
    static void context(Connection c,UUID delivery,UUID player,String town,String project)throws SQLException{
        id(project);town=town(town);var p=project(c,project);if(p.isEmpty()||!p.get("state").equals("OPEN"))throw new IllegalArgumentException("Общая стройка закрыта или не найдена");
        try(var s=c.prepareStatement("SELECT player,state FROM deliveries WHERE id=?")){s.setString(1,delivery.toString());try(var r=s.executeQuery()){if(!r.next()||!r.getString(1).equals(player.toString())||!r.getString(2).equals("PREPARED"))throw new IllegalArgumentException("Направление задаётся до подтверждения поставки");}}
        try(var s=c.prepareStatement("SELECT project,town,player FROM cooperative_context WHERE delivery=?")){s.setString(1,delivery.toString());try(var r=s.executeQuery()){if(r.next()){if(!r.getString(1).equals(project)||!r.getString(2).equals(town)||!r.getString(3).equals(player.toString()))throw new IllegalArgumentException("Поставка уже закреплена за другой стройкой или городом");return;}}}
        try(var s=c.prepareStatement("INSERT INTO cooperative_context VALUES(?,?,?,?)")){s.setString(1,delivery.toString());s.setString(2,project);s.setString(3,town);s.setString(4,player.toString());s.executeUpdate();}
    }
    /** Confirmed paid items move from global availability to a project reserve in the SAME stock-credit transaction. */
    static void confirmed(Connection c,ServerMaterials.Delivery delivery)throws SQLException{
        String project,town,player;try(var s=c.prepareStatement("SELECT project,town,player FROM cooperative_context WHERE delivery=?")){s.setString(1,delivery.id().toString());try(var r=s.executeQuery()){if(!r.next())return;project=r.getString(1);town=r.getString(2);player=r.getString(3);}}
        long missing;try(var s=c.prepareStatement("SELECT n.amount-COALESCE((SELECT SUM(x.amount) FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.project=n.project AND x.material=n.material AND a.state IN ('RESERVED','SPENT')),0) FROM cooperative_needs n JOIN cooperative_projects p ON p.id=n.project WHERE n.project=? AND n.material=? AND p.state='OPEN'")){s.setString(1,project);s.setString(2,delivery.material());try(var r=s.executeQuery()){if(!r.next())return;missing=r.getLong(1);}}
        long amount=Math.min(delivery.amount(),Math.max(0,missing));if(amount==0)return;String allocation=UUID.nameUUIDFromBytes(("neverland-cooperative-delivery:"+delivery.id()).getBytes(StandardCharsets.UTF_8)).toString();long now=System.currentTimeMillis();
        try(var s=c.prepareStatement("INSERT INTO allocations(id,project,actor,reason,state,created) VALUES(?,?,?,?,'RESERVED',?)")){s.setString(1,allocation);s.setString(2,project);s.setString(3,player);s.setString(4,"cooperative confirmed delivery "+delivery.id());s.setLong(5,now);s.executeUpdate();}
        try(var s=c.prepareStatement("UPDATE balances SET available=available-? WHERE material=? AND available>=?")){s.setLong(1,amount);s.setString(2,delivery.material());s.setLong(3,amount);if(s.executeUpdate()!=1)throw new SQLException("Подтверждённая поставка не обеспечена складом");}
        try(var s=c.prepareStatement("INSERT INTO allocation_items VALUES(?,?,?)")){s.setString(1,allocation);s.setString(2,delivery.material());s.setLong(3,amount);s.executeUpdate();}
        try(var s=c.prepareStatement("INSERT INTO cooperative_contributions VALUES(?,?,?,?,?,?,?,?)")){s.setString(1,delivery.id().toString());s.setString(2,project);s.setString(3,town);s.setString(4,player);s.setString(5,delivery.material());s.setLong(6,amount);s.setString(7,allocation);s.setLong(8,now);s.executeUpdate();}
    }
    static Map<String,Object> project(Connection c,String id)throws SQLException{
        var out=new LinkedHashMap<String,Object>();try(var s=c.prepareStatement("SELECT * FROM cooperative_projects WHERE id=?")){s.setString(1,id);try(var r=s.executeQuery()){if(!r.next())return Map.of();out.put("id",id);out.put("title",r.getString("title"));out.put("scope",r.getString("scope"));out.put("ownerTown",r.getString("owner_town"));out.put("unlock",r.getString("unlock_key"));out.put("minimumCredit",r.getLong("min_credit"));out.put("state",r.getString("state"));out.put("created",r.getLong("created"));out.put("completed",r.getLong("completed"));}}
        var needs=new TreeMap<String,Long>();try(var s=c.prepareStatement("SELECT material,amount FROM cooperative_needs WHERE project=? ORDER BY material")){s.setString(1,id);try(var r=s.executeQuery()){while(r.next())needs.put(r.getString(1),r.getLong(2));}}
        var credited=new TreeMap<String,Long>();try(var s=c.prepareStatement("SELECT x.material,SUM(x.amount) FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.project=? AND a.state IN ('RESERVED','SPENT') GROUP BY x.material")){s.setString(1,id);try(var r=s.executeQuery()){while(r.next())credited.put(r.getString(1),r.getLong(2));}}
        var cities=new TreeMap<String,Long>();try(var s=c.prepareStatement("SELECT x.town,SUM(x.amount) FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.project=? AND a.state IN ('RESERVED','SPENT') GROUP BY x.town ORDER BY SUM(x.amount) DESC,x.town LIMIT 100")){s.setString(1,id);try(var r=s.executeQuery()){while(r.next())cities.put(r.getString(1),r.getLong(2));}}
        out.put("needs",Map.copyOf(needs));out.put("credited",Map.copyOf(credited));out.put("cities",Map.copyOf(cities));out.put("funded",needs.entrySet().stream().allMatch(e->credited.getOrDefault(e.getKey(),0L)>=e.getValue()));return Map.copyOf(out);
    }
    static List<Map<String,Object>> list(Connection c,int page)throws SQLException{if(page<1||page>100_000)throw new IllegalArgumentException("Неверная страница");var ids=new ArrayList<String>();try(var s=c.prepareStatement("SELECT id FROM cooperative_projects ORDER BY created DESC,id LIMIT 20 OFFSET ?")){s.setLong(1,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())ids.add(r.getString(1));}}var out=new ArrayList<Map<String,Object>>();for(String id:ids)out.add(project(c,id));return List.copyOf(out);}
    static List<Map<String,Object>> receipts(Connection c,UUID town,int page)throws SQLException{if(page<1||page>100_000)throw new IllegalArgumentException("Неверная страница");var out=new ArrayList<Map<String,Object>>();try(var s=c.prepareStatement("SELECT x.delivery,x.project,x.player,x.material,x.amount,a.state,x.confirmed FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.town=? ORDER BY x.confirmed DESC,x.delivery LIMIT 20 OFFSET ?")){s.setString(1,town.toString());s.setLong(2,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())out.add(Map.of("delivery",r.getString(1),"project",r.getString(2),"player",r.getString(3),"material",r.getString(4),"amount",r.getLong(5),"state",r.getString(6),"at",r.getLong(7)));}}return List.copyOf(out);}
    static Set<String> unlocked(Connection c,UUID town)throws SQLException{var out=new TreeSet<String>();try(var s=c.prepareStatement("SELECT p.unlock_key FROM cooperative_projects p JOIN cooperative_contributions x ON x.project=p.id JOIN allocations a ON a.id=x.allocation WHERE p.state='COMPLETED' AND a.state='SPENT' AND x.town=? AND (p.scope='SERVER' OR p.owner_town=?) GROUP BY p.id HAVING SUM(x.amount)>=p.min_credit")){s.setString(1,town.toString());s.setString(2,town.toString());try(var r=s.executeQuery()){while(r.next())out.add(r.getString(1));}}return Set.copyOf(out);}
    static Map<String,Object> finish(Connection c,String id,boolean cancel,String actor,String reason)throws SQLException{
        id(id);text(actor,64,"автор");text(reason,500,"основание");if(reason.trim().length()<8)throw new IllegalArgumentException("Укажите основание не короче 8 символов");var p=project(c,id);if(p.isEmpty())throw new IllegalArgumentException("Стройка не найдена");String goal=cancel?"CANCELLED":"COMPLETED";if(p.get("state").equals(goal))return p;if(!p.get("state").equals("OPEN"))throw new IllegalArgumentException("Закрытую стройку нельзя изменить");if(!cancel&&!Boolean.TRUE.equals(p.get("funded")))throw new IllegalArgumentException("Не все материалы подтверждены и зарезервированы");
        if(cancel){
            try(var s=c.prepareStatement("SELECT 1 FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.project=? AND a.state='SPENT' LIMIT 1")){s.setString(1,id);try(var r=s.executeQuery()){if(r.next())throw new IllegalArgumentException("Часть материалов уже использована; отмена требует отдельного проекта восстановления");}}
            try(var s=c.prepareStatement("UPDATE balances SET available=available+(SELECT COALESCE(SUM(x.amount),0) FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.project=? AND x.material=balances.material AND a.state='RESERVED') WHERE material IN (SELECT x.material FROM cooperative_contributions x JOIN allocations a ON a.id=x.allocation WHERE x.project=? AND a.state='RESERVED')")){s.setString(1,id);s.setString(2,id);s.executeUpdate();}
        }
        try(var s=c.prepareStatement("UPDATE allocations SET state=?,decision=? WHERE state='RESERVED' AND id IN (SELECT allocation FROM cooperative_contributions WHERE project=?)")){s.setString(1,cancel?"RETURNED":"SPENT");s.setString(2,"cooperative "+goal+" by "+actor+": "+reason);s.setString(3,id);s.executeUpdate();}
        try(var s=c.prepareStatement("UPDATE cooperative_projects SET state=?,completed=? WHERE id=? AND state='OPEN'")){s.setString(1,goal);s.setLong(2,System.currentTimeMillis());s.setString(3,id);s.executeUpdate();}log(c,id,goal,actor,reason);return project(c,id);
    }
    static List<Map<String,Object>> history(Connection c,String project)throws SQLException{var out=new ArrayList<Map<String,Object>>();try(var s=c.prepareStatement("SELECT action,actor,reason,at FROM cooperative_actions WHERE project=? ORDER BY at,action")){s.setString(1,project);try(var r=s.executeQuery()){while(r.next())out.add(Map.of("action",r.getString(1),"actor",r.getString(2),"reason",r.getString(3),"at",r.getLong(4)));}}return List.copyOf(out);}
    static void log(Connection c,String project,String action,String actor,String reason)throws SQLException{try(var s=c.prepareStatement("INSERT OR IGNORE INTO cooperative_actions VALUES(?,?,?,?,?)")){s.setString(1,project);s.setString(2,action);s.setString(3,actor);s.setString(4,reason);s.setLong(5,System.currentTimeMillis());s.executeUpdate();}}
}
